import React, { useState, useEffect } from "react";
import { BrowserRouter as Router, Route, Routes, Link } from "react-router-dom";
import { Sun, Moon } from "lucide-react";
import { CSVLink } from "react-csv";
import { FaUserCircle } from "react-icons/fa";

// Component imports
import ExpensesChartPage from "./components/ExpensesChartPage";
import BudgetSummary from "./components/BudgetSummary";
import WishlistPage from "./components/WishlistPage";
import Savings from "./components/Savings";
import { LoginForm } from "./components/LoginForm";
import { SignUpForm } from "./components/SignUpForm";
import Modal from "./components/Modal";
import MySubscriptionsPage from "./components/MySubscriptionsPage";
import MyIncomePage from "./components/MyIncomePage";
import DashboardPage from "./components/DashboardPage";
import TransactionEntryComponent from "./components/TransactionEntryComponent"; // Ensure this path is correct

// Asset imports
import csvIcon from "./assets/img/csv-icon.png";
import googleSheetsIcon from "./assets/img/google-sheets-icon.png";

// Type definitions
export interface Transaction {
  id: string;
  description: string;
  amount: number;
  date: string;
  type: 'income' | 'expense';
  category: string;
}

interface AppProps {
  expenses: Transaction[];
  isDarkTheme: boolean;
}

const App: React.FC<AppProps> = ({ expenses, isDarkTheme: initialDarkTheme }) => {
  // State declarations
  const [isDarkTheme, setIsDarkTheme] = useState(initialDarkTheme);
  const [showAuthModal, setShowAuthModal] = useState(false);
  const [isLogin, setIsLogin] = useState(true);
  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [incomeCategories, setIncomeCategories] = useState<string[]>(["Salary", "Freelance", "Investments"]);
  const [expenseCategories, setExpenseCategories] = useState<string[]>(["Rent", "Groceries", "Utilities", "Entertainment"]);
  const [monthlyBudget, setMonthlyBudget] = useState<number>(5000);
  const [savingsGoal, setSavingsGoal] = useState<number>(10000);

  // Utility functions
  const toggleTheme = () => setIsDarkTheme(!isDarkTheme);
  const toggleAuthModal = () => setShowAuthModal(!showAuthModal);
  const toggleAuthForm = () => setIsLogin(!isLogin);

  // Derived state
  const income = transactions.filter(t => t.type === 'income');
  const totalIncome = income.reduce((sum, item) => sum + item.amount, 0);
  const totalExpenses = expenses.reduce((sum, item) => sum + item.amount, 0);
  const balance = totalIncome - totalExpenses;

  // Handler functions
  const handleAddTransaction = (newTransaction: Omit<Transaction, 'id'>) => {
    const transactionWithId = {
      ...newTransaction,
      id: '_' + Math.random().toString(36).substring(2, 11)
    };
    setTransactions(prevTransactions => [...prevTransactions, transactionWithId]);
  };

  const handleAddCategory = (type: "income" | "expense", newCategory: string) => {
    if (newCategory) {
      if (type === "income") {
        setIncomeCategories(prev => [...prev, newCategory]);
      } else {
        setExpenseCategories(prev => [...prev, newCategory]);
      }
    }
  };

  const handleDeleteTransaction = (id: string) => {
    setTransactions(prevTransactions => prevTransactions.filter(t => t.id !== id));
  };

  const handleUpdateTransaction = (updatedTransaction: Transaction) => {
    setTransactions(prevTransactions =>
      prevTransactions.map(t => t.id === updatedTransaction.id ? updatedTransaction : t)
    );
  };

  const handleUpdateBudget = (newBudget: number) => {
    setMonthlyBudget(newBudget);
  };

  const handleUpdateSavingsGoal = (newGoal: number) => {
    setSavingsGoal(newGoal);
  };

  // useEffect hooks for data persistence
  useEffect(() => {
    const savedTransactions = localStorage.getItem('transactions');
    if (savedTransactions) {
      setTransactions(JSON.parse(savedTransactions));
    }
    const savedBudget = localStorage.getItem('monthlyBudget');
    if (savedBudget) {
      setMonthlyBudget(JSON.parse(savedBudget));
    }
    const savedGoal = localStorage.getItem('savingsGoal');
    if (savedGoal) {
      setSavingsGoal(JSON.parse(savedGoal));
    }
  }, []);

  useEffect(() => {
    localStorage.setItem('transactions', JSON.stringify(transactions));
  }, [transactions]);

  useEffect(() => {
    localStorage.setItem('monthlyBudget', JSON.stringify(monthlyBudget));
  }, [monthlyBudget]);

  useEffect(() => {
    localStorage.setItem('savingsGoal', JSON.stringify(savingsGoal));
  }, [savingsGoal]);

  // CSV export configuration
  const csvHeaders = [
    { label: "Description", key: "description" },
    { label: "Amount", key: "amount" },
    { label: "Date", key: "date" },
    { label: "Type", key: "type" },
    { label: "Category", key: "category" },
  ];

  return (
    <Router>
      <div className={`min-h-screen ${isDarkTheme ? "bg-gray-900 text-white" : "bg-gray-100 text-black"}`}>
        <header className="bg-indigo-600 text-white p-4 flex justify-between items-center">
          <h1 className="text-2xl font-bold">Budget App</h1>
          <nav>
            <Link to="/" className="mr-4">Home</Link>
            <Link to="/expenses-chart" className="mr-4">Expenses</Link>
            <Link to="/wishlist" className="mr-4">Wishlist</Link>
            <Link to="/savings" className="mr-4">Savings</Link>
            <Link to="/subscriptions" className="mr-4">Subscriptions</Link>
            <Link to="/income" className="mr-4">My Income</Link>
            <Link to="/dashboard">Dashboard</Link>
          </nav>
          <div className="flex items-center">
            <FaUserCircle size={24} className="mr-2 cursor-pointer" onClick={toggleAuthModal} />
            <span className="cursor-pointer" onClick={toggleAuthModal}>Connect</span>
            {isDarkTheme ? (
              <Sun className="ml-4 cursor-pointer" onClick={toggleTheme} />
            ) : (
              <Moon className="ml-4 cursor-pointer" onClick={toggleTheme} />
            )}
          </div>
        </header>

        <Routes>
          <Route path="/" element={
            <main className="container mx-auto p-4">
              <TransactionEntryComponent
                onAddTransaction={handleAddTransaction}
                onAddCategory={handleAddCategory}
                incomeCategories={incomeCategories}
                expenseCategories={expenseCategories}
                isDarkTheme={isDarkTheme}
              />
              <div className="mt-8">
                <BudgetSummary
                  totalIncome={totalIncome}
                  totalExpenses={totalExpenses}
                  monthlyBudget={monthlyBudget}
                  onUpdateBudget={handleUpdateBudget}
                />
              </div>
              <div className="mt-4 flex justify-end space-x-2">
                <CSVLink data={transactions} headers={csvHeaders} filename="transactions.csv" className="inline-block">
                  <img src={csvIcon} alt="CSV Icon" className="w-6 h-6" />
                </CSVLink>
                <button className="inline-block">
                  <img src={googleSheetsIcon} alt="Google Sheets Icon" className="w-6 h-6" />
                </button>
              </div>
            </main>
          } />
          <Route path="/expenses-chart" element={
            <ExpensesChartPage
              expenses={expenses}
              isDarkTheme={isDarkTheme}
            />
          } />
          <Route path="/wishlist" element={<WishlistPage />} />
          <Route path="/savings" element={
            <Savings
              balance={balance}
              savingsGoal={savingsGoal}
              onUpdateSavingsGoal={handleUpdateSavingsGoal}
            />
          } />
          <Route path="/subscriptions" element={
            <MySubscriptionsPage
              subscriptions={expenses.filter(e => e.category === "Subscription")}
              onCancelSubscription={handleDeleteTransaction}
            />
          } />
          <Route path="/income" element={
            <MyIncomePage
              income={income}
              onDeleteIncome={handleDeleteTransaction}
              onUpdateIncome={handleUpdateTransaction}
            />
          } />
          <Route path="/dashboard" element={
            <DashboardPage
              income={income}
              expenses={expenses}
              monthlyBudget={monthlyBudget}
              savingsGoal={savingsGoal}
              onUpdateTransaction={handleUpdateTransaction}
              onDeleteTransaction={handleDeleteTransaction}
              onUpdateBudget={handleUpdateBudget}
              onUpdateSavingsGoal={handleUpdateSavingsGoal}
            />
          } />
        </Routes>

        <Modal isOpen={showAuthModal} onClose={toggleAuthModal}>
          {isLogin ? (
            <LoginForm onSwitchForm={toggleAuthForm} />
          ) : (
            <SignUpForm onSwitchForm={toggleAuthForm} />
          )}
        </Modal>
      </div>
    </Router>
  );
};

export default App;