import React, { useState, useEffect, useCallback } from "react";
import {
  LineChart,
  Line,
  BarChart,
  Bar,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  ResponsiveContainer,
} from "recharts";
import {
  Bell,
  Home,
  MessageSquare,
  Star,
  Settings,
  LogOut,
  RefreshCw,
} from "lucide-react";
import { Transaction } from '../App';

interface DashboardData {
  totalIncome: number;
  totalExpenses: number;
  balance: number;
  recentTransactions: Transaction[];
  monthlyData: { month: string; income: number; expenses: number }[];
  performanceData: { name: string; value: number }[];
}

interface DashboardPageProps {
  income: Transaction[];
  expenses: Transaction[];
  monthlyBudget: number;
  savingsGoal: number;
  onUpdateTransaction: (updatedTransaction: Transaction) => void;
  onDeleteTransaction: (id: string) => void;
  onUpdateBudget: (newBudget: number) => void;
  onUpdateSavingsGoal: (newGoal: number) => void;
}

const DashboardPage: React.FC<DashboardPageProps> = ({
  income,
  expenses,
  monthlyBudget,
  savingsGoal,
  onUpdateTransaction,
  onDeleteTransaction,
  onUpdateBudget,
  onUpdateSavingsGoal,
}) => {
  const [dashboardData, setDashboardData] = useState<DashboardData | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [incomeChange, setIncomeChange] = useState(0);
  const [expensesChange, setExpensesChange] = useState(0);
  const [balanceChange, setBalanceChange] = useState(0);

  const calculatePercentageChange = (current: number, previous: number) => {
    if (previous === 0) return current === 0 ? 0 : 100;
    return ((current - previous) / previous) * 100;
  };

  const calculateDashboardData = useCallback(() => {
    const totalIncome = income.reduce((sum, item) => sum + item.amount, 0);
    const totalExpenses = expenses.reduce((sum, item) => sum + item.amount, 0);
    const balance = totalIncome - totalExpenses;

    const recentTransactions = [...income, ...expenses]
      .sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime())
      .slice(0, 5);

    const monthlyData = [
      { month: "Jan", income: 0, expenses: 0 },
      { month: "Feb", income: 0, expenses: 0 },
      { month: "Mar", income: 0, expenses: 0 },
      // Add more months as needed
    ];

    // Populate monthlyData with actual data
    [...income, ...expenses].forEach((transaction) => {
      const month = new Date(transaction.date).getMonth();
      if (transaction.type === 'income') {
        monthlyData[month].income += transaction.amount;
      } else {
        monthlyData[month].expenses += transaction.amount;
      }
    });

    const performanceData = monthlyData.map((data) => ({
      name: data.month,
      value: data.income - data.expenses,
    }));

    return {
      totalIncome,
      totalExpenses,
      balance,
      recentTransactions,
      monthlyData,
      performanceData,
    };
  }, [income, expenses]);

  useEffect(() => {
    setIsLoading(true);
    setError(null);
    try {
      const data = calculateDashboardData();
      setDashboardData(data);

      // Calculate percentage changes
      const previousMonthData = data.monthlyData[data.monthlyData.length - 2];
      const currentMonthData = data.monthlyData[data.monthlyData.length - 1];

      if (previousMonthData && currentMonthData) {
        setIncomeChange(calculatePercentageChange(currentMonthData.income, previousMonthData.income));
        setExpensesChange(calculatePercentageChange(currentMonthData.expenses, previousMonthData.expenses));
        setBalanceChange(calculatePercentageChange(data.balance, data.balance - (currentMonthData.income - currentMonthData.expenses)));
      }
    } catch (err) {
      console.error("Error calculating dashboard data:", err);
      setError(
        "An error occurred while calculating dashboard data. Please try again."
      );
    } finally {
      setIsLoading(false);
    }
  }, [calculateDashboardData]);

  const handleRetry = () => {
    const data = calculateDashboardData();
    setDashboardData(data);
  };

  const formatCurrency = (value: number) => {
    return value.toLocaleString(undefined, {
      minimumFractionDigits: 2,
      maximumFractionDigits: 2,
    });
  };

  if (isLoading) {
    return (
      <div className="flex justify-center items-center h-screen">
        <div className="animate-spin rounded-full h-32 w-32 border-t-2 border-b-2 border-gray-900"></div>
      </div>
    );
  }

  if (error || !dashboardData) {
    return (
      <div className="flex flex-col justify-center items-center h-screen">
        <p className="text-red-500 mb-4">
          {error || "Failed to load dashboard data."}
        </p>
        <button
          onClick={handleRetry}
          className="px-4 py-2 bg-blue-500 text-white rounded hover:bg-blue-600 transition duration-300"
        >
          <RefreshCw className="w-4 h-4 mr-2 inline" />
          Retry
        </button>
      </div>
    );
  }

  const currentDate = new Date();
  const daysInMonth = new Date(
    currentDate.getFullYear(),
    currentDate.getMonth() + 1,
    0
  ).getDate();

  return (
    <div className="flex bg-gray-100 min-h-screen">
      {/* Sidebar */}
      <aside className="w-16 bg-teal-500 text-white p-4 flex flex-col items-center justify-between">
        <div className="space-y-8">
          <Home className="w-6 h-6" />
          <MessageSquare className="w-6 h-6" />
          <Star className="w-6 h-6" />
          <Settings className="w-6 h-6" />
        </div>
        <LogOut className="w-6 h-6" />
      </aside>

      {/* Main content */}
      <main className="flex-1 p-8">
        <div className="flex justify-between items-center mb-8">
          <h1 className="text-3xl font-bold">Dashboard</h1>
          <div className="flex items-center space-x-4">
            <input
              type="text"
              placeholder="Search..."
              className="px-4 py-2 border rounded-full"
            />
            <Bell className="w-6 h-6 text-gray-500" />
          </div>
        </div>

        {/* Summary Cards */}
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-8">
          {/* Total Income Card */}
          <div className="bg-white p-6 rounded-lg shadow-md">
            <div className="flex justify-between items-center mb-2">
              <h2 className="text-sm font-medium text-gray-600">
                Total Income
              </h2>
            </div>
            <div className="text-2xl font-bold">
              {formatCurrency(dashboardData.totalIncome)} €
            </div>
            <p className={`text-xs ${incomeChange >= 0 ? 'text-green-500' : 'text-red-500'}`}>
              {incomeChange >= 0 ? '+' : ''}{incomeChange.toFixed(1)}% from last month
            </p>
          </div>

          {/* Total Expenses Card */}
          <div className="bg-white p-6 rounded-lg shadow-md">
            <div className="flex justify-between items-center mb-2">
              <h2 className="text-sm font-medium text-gray-600">
                Total Expenses
              </h2>
            </div>
            <div className="text-2xl font-bold">
              {formatCurrency(dashboardData.totalExpenses)} €
            </div>
            <p className={`text-xs ${expensesChange <= 0 ? 'text-green-500' : 'text-red-500'}`}>
              {expensesChange >= 0 ? '+' : ''}{expensesChange.toFixed(1)}% from last month
            </p>
          </div>

          {/* Balance Card */}
          <div className="bg-white p-6 rounded-lg shadow-md">
            <div className="flex justify-between items-center mb-2">
              <h2 className="text-sm font-medium text-gray-600">Balance</h2>
            </div>
            <div className="text-2xl font-bold">
              {formatCurrency(dashboardData.balance)} €
            </div>
            <p className={`text-xs ${balanceChange >= 0 ? 'text-green-500' : 'text-red-500'}`}>
              {balanceChange >= 0 ? '+' : ''}{balanceChange.toFixed(1)}% from last month
            </p>
          </div>
        </div>

        {/* Charts */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-8">
          {/* Monthly Overview */}
          <div className="bg-white p-6 rounded-lg shadow-md">
            <h2 className="text-lg font-semibold mb-4">Monthly Overview</h2>
            <ResponsiveContainer width="100%" height={300}>
              <LineChart data={dashboardData.monthlyData}>
                <CartesianGrid strokeDasharray="3 3" />
                <XAxis dataKey="month" />
                <YAxis />
                <Tooltip />
                <Line type="monotone" dataKey="income" stroke="#8884d8" />
                <Line type="monotone" dataKey="expenses" stroke="#82ca9d" />
              </LineChart>
            </ResponsiveContainer>
          </div>

          {/* Performance */}
          <div className="bg-white p-6 rounded-lg shadow-md">
            <h2 className="text-lg font-semibold mb-4">Performance</h2>
            <ResponsiveContainer width="100%" height={300}>
              <BarChart data={dashboardData.performanceData}>
                <CartesianGrid strokeDasharray="3 3" />
                <XAxis dataKey="name" />
                <YAxis />
                <Tooltip />
                <Bar dataKey="value" fill="#8884d8" />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>

        {/* Calendar and Progress */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-8">
          {/* Calendar */}
          <div className="bg-white p-6 rounded-lg shadow-md">
            <h2 className="text-lg font-semibold mb-4">Calendar</h2>
            <div className="grid grid-cols-7 gap-2">
              {Array.from({ length: daysInMonth }, (_, i) => i + 1).map(
                (day) => (
                  <div
                    key={day}
                    className={`aspect-square flex items-center justify-center rounded-full ${
                      day === currentDate.getDate()
                        ? "bg-blue-500 text-white"
                        : "hover:bg-gray-100"
                    }`}
                  >
                    {day}
                  </div>
                )
              )}
            </div>
          </div>

          {/* Progress */}
          <div className="bg-white p-6 rounded-lg shadow-md">
            <h2 className="text-lg font-semibold mb-4">Progress</h2>
            <div className="space-y-4">
              <div>
                <div className="flex justify-between mb-1">
                  <span className="text-sm font-medium">Monthly Budget</span>
                  <span className="text-sm font-medium">
                    {((dashboardData.totalExpenses / monthlyBudget) * 100).toFixed(1)}%
                  </span>
                </div>
                <div className="w-full bg-gray-200 rounded-full h-2.5">
                  <div
                    className="bg-blue-600 h-2.5 rounded-full"
                    style={{ width: `${(dashboardData.totalExpenses / monthlyBudget) * 100}%` }}
                  ></div>
                </div>
              </div>
              <div>
                <div className="flex justify-between mb-1">
                  <span className="text-sm font-medium">Savings Goal</span>
                  <span className="text-sm font-medium">
                    {((dashboardData.balance / savingsGoal) * 100).toFixed(1)}%
                  </span>
                </div>
                <div className="w-full bg-gray-200 rounded-full h-2.5">
                  <div
                    className="bg-green-500 h-2.5 rounded-full"
                    style={{ width: `${(dashboardData.balance / savingsGoal) * 100}%` }}
                  ></div>
                </div>
              </div>
            </div>
          </div>
        </div>

        {/* Recent Transactions */}
        <div className="bg-white p-6 rounded-lg shadow-md">
          <h2 className="text-lg font-semibold mb-4">Recent Transactions</h2>
          <ul className="divide-y divide-gray-200">
            {dashboardData.recentTransactions.map((transaction) => (
              <li
                key={transaction.id}
                className="py-4 flex justify-between items-center"
              >
                <div>
                  <p className="text-sm font-medium text-gray-900">
                    {transaction.description}
                  </p>
                  <p className="text-sm text-gray-500">{transaction.date}</p>
                </div>
                <span
                  className={`text-sm font-medium ${
                    transaction.type === "income"
                      ? "text-green-600"
                      : "text-red-600"
                  }`}
                >
                  {transaction.type === "income" ? "+" : "-"}
                  {formatCurrency(transaction.amount)} €
                </span>
              </li>
            ))}
          </ul>
        </div>
      </main>
    </div>
  );
};

export default DashboardPage;