import React from 'react';

interface SavingsProps {
  balance: number;
  savingsGoal: number;
  onUpdateSavingsGoal: (newGoal: number) => void;
}

const Savings: React.FC<SavingsProps> = ({ balance, savingsGoal, onUpdateSavingsGoal }) => {
  const handleSavingsGoalChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const newGoal = parseFloat(event.target.value);
    if (!isNaN(newGoal)) {
      onUpdateSavingsGoal(newGoal);
    }
  };

  return (
    <div className="bg-blue-100 p-6 rounded-lg shadow-md">
      <h2 className="text-lg font-semibold mb-4">Savings</h2>
      <div className="mb-4">
        <h3 className="text-md font-medium">Current Balance</h3>
        <p className="text-blue-600 text-2xl font-bold">
          {balance.toFixed(2)} €
        </p>
      </div>
      <div className="mb-4">
        <h3 className="text-md font-medium">Savings Goal</h3>
        <input
          type="number"
          value={savingsGoal}
          onChange={handleSavingsGoalChange}
          className="border rounded p-2 w-full"
        />
      </div>
      <div>
        <h3 className="text-md font-medium">Progress</h3>
        <div className="w-full bg-gray-200 rounded-full h-2.5">
          <div
            className="bg-blue-600 h-2.5 rounded-full"
            style={{ width: `${(balance / savingsGoal) * 100}%` }}
          ></div>
        </div>
      </div>
    </div>
  );
};

export default Savings;